use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let cs: Vec<char> = line.chars().collect()
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut i = 0
        while i < cs.len() {
            let c = cs[i]
            if inq {
                if c == '"' {
                    if i + 1 < cs.len() && cs[i + 1] == '"' {
                        cur.push('"')
                        i += 1
                    } else {
                        inq = false
                    }
                } else {
                    cur.push(c)
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else {
                cur.push(c)
            }
            i += 1
        }
        fields.push(cur)
        let parts: Vec<string> = fields.map(|f| "[${f}]").collect()
        println("${fields.len()}: ${parts.join("|")}")
    }
}

